export enum Subject {
  PHYSICS = 'Physics',
  CHEMISTRY = 'Chemistry',
  BIOLOGY = 'Biology',
  MATH = 'Mathematics',
  ICT = 'ICT'
}

export interface SyllabusItem {
  id: string;
  subject: Subject;
  chapterNumber: number;
  chapterTitle: string;
  topics: string[];
}

export type QuestionType = 'MCQ' | 'CQ';

export interface MCQOption {
  id: string;
  text: string;
}

export interface MCQQuestion {
  id: string;
  type: 'MCQ';
  chapter: string;
  question: string;
  options: MCQOption[];
  correctOptionId: string;
  explanation: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
}

export interface CQQuestion {
  id: string;
  type: 'CQ';
  chapter: string;
  stem: string; // The scenario/passage
  parts: {
    a: { question: string; marks: number; label: 'Knowledge' };
    b: { question: string; marks: number; label: 'Understanding' };
    c: { question: string; marks: number; label: 'Application' };
    d: { question: string; marks: number; label: 'Higher Order' };
  };
}

export type Question = MCQQuestion | CQQuestion;

export interface ExamSession {
  id: string;
  subject: Subject;
  mode: 'Practice' | 'Exam';
  startTime: number;
  questions: Question[];
  durationMinutes: number;
  isCompleted: boolean;
}

export interface GradingResult {
  questionId: string;
  obtainedMarks: number;
  maxMarks: number;
  feedback: string;
  status: 'Correct' | 'Partial' | 'Incorrect';
}

export interface AnalyticsData {
  subject: Subject;
  accuracy: number;
  averageScore: number;
  totalExams: number;
  weakChapters: string[];
}

