import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number = 5): Promise<MCQQuestion[]> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate ${count} high-quality board-style MCQ questions for SSC Bangladesh exam. 
      Subject: ${subject}, Chapter: ${chapter}. 
      Follow the 2026 syllabus guidelines.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                  },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string): Promise<CQQuestion | null> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate one original SSC Creative Question (CQ) with a stem and 4 parts (a, b, c, d).
      Subject: ${subject}, Chapter: ${chapter}.
      A: Knowledge (1 mark), B: Understanding (2 marks), C: Application (3 marks), D: Higher Order (4 marks).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } },
                b: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } },
                c: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } },
                d: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } }
              }
            }
          }
        }
      }
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      return null;
    }
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, string>): Promise<GradingResult[]> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Grade the following student's answers for an SSC CQ based on Bangladesh Board marking rules.
      Question Stem: ${question.stem}
      A: ${question.parts.a.question}
      B: ${question.parts.b.question}
      C: ${question.parts.c.question}
      D: ${question.parts.d.question}

      Student Answers:
      A: ${answers.a}
      B: ${answers.b}
      C: ${answers.c}
      D: ${answers.d}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            }
          }
        }
      }
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      return [];
    }
  }
};

