import React, { useState, useEffect } from 'react';
import { Timer } from 'lucide-react';

interface ExamTimerProps {
  durationMinutes: number;
  onTimeUp: () => void;
}

const ExamTimer: React.FC<ExamTimerProps> = ({ durationMinutes, onTimeUp }) => {
  const [timeLeft, setTimeLeft] = useState(durationMinutes * 60);

  useEffect(() => {
    if (timeLeft <= 0) {
      onTimeUp();
      return;
    }

    const interval = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);

    return () => clearInterval(interval);
  }, [timeLeft, onTimeUp]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const isLow = timeLeft < 300; // Less than 5 mins

  return (
    <div className={`flex items-center gap-2 px-4 py-2 rounded-full border ${
      isLow ? 'bg-red-950/30 border-red-800 text-red-400' : 'bg-slate-900 border-slate-800 text-slate-300'
    }`}>
      <Timer size={18} className={isLow ? 'animate-pulse' : ''} />
      <span className="font-mono text-lg font-bold">{formatTime(timeLeft)}</span>
    </div>
  );
};

export default ExamTimer;

import React from 'react';
import { Question, MCQQuestion, CQQuestion } from '../types';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: any;
  onAnswerChange: (answer: any) => void;
  showFeedback?: boolean;
}

const QuestionRenderer: React.FC<QuestionRendererProps> = ({ 
  question, 
  index, 
  answer, 
  onAnswerChange,
  showFeedback = false 
}) => {
  if (question.type === 'MCQ') {
    const mcq = question as MCQQuestion;
    return (
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
        <div className="flex items-start gap-4 mb-6">
          <span className="flex-shrink-0 w-8 h-8 rounded-lg bg-indigo-600/20 text-indigo-400 flex items-center justify-center font-bold text-sm">
            {index + 1}
          </span>
          <h3 className="text-lg font-medium text-slate-200 leading-relaxed">
            {mcq.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {mcq.options.map((option) => {
            const isSelected = answer === option.id;
            const isCorrect = option.id === mcq.correctOptionId;
            let borderStyle = 'border-slate-800 hover:border-slate-700 hover:bg-slate-800/50';

            if (isSelected) borderStyle = 'border-indigo-500 bg-indigo-500/10 text-indigo-200';
            if (showFeedback) {
              if (isCorrect) borderStyle = 'border-emerald-500 bg-emerald-500/10 text-emerald-200';
              else if (isSelected) borderStyle = 'border-red-500 bg-red-500/10 text-red-200';
            }

            return (
              <button
                key={option.id}
                onClick={() => !showFeedback && onAnswerChange(option.id)}
                disabled={showFeedback}
                className={`flex items-center gap-3 p-4 rounded-xl border transition-all text-left ${borderStyle}`}
              >
                <div className={`w-6 h-6 rounded-full border flex items-center justify-center flex-shrink-0 ${
                  isSelected ? 'border-indigo-500 bg-indigo-500' : 'border-slate-700'
                }`}>
                  {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-white"></div>}
                </div>
                <span className="text-sm md:text-base font-medium">{option.text}</span>
              </button>
            );
          })}
        </div>

        {showFeedback && (
          <div className="mt-6 p-4 bg-slate-800/50 rounded-xl border border-slate-700">
            <h4 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">Explanation</h4>
            <p className="text-sm text-slate-300 leading-relaxed">{mcq.explanation}</p>
          </div>
        )}
      </div>
    );
  }

  const cq = question as CQQuestion;
  const cqAnswers = answer || { a: '', b: '', c: '', d: '' };

  const updatePart = (part: 'a' | 'b' | 'c' | 'd', val: string) => {
    onAnswerChange({ ...cqAnswers, [part]: val });
  };

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
      <div className="bg-slate-950 p-6 rounded-xl border border-slate-800 mb-8">
        <h4 className="text-xs font-bold text-indigo-400 uppercase mb-3 tracking-widest">Stem / উদ্দীপক</h4>
        <p className="text-slate-200 leading-relaxed whitespace-pre-wrap">{cq.stem}</p>
      </div>

      <div className="space-y-8">
        {(['a', 'b', 'c', 'd'] as const).map((part) => (
          <div key={part} className="space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-slate-300 font-medium flex items-center gap-2">
                <span className="uppercase text-indigo-500 font-bold">{part})</span>
                {cq.parts[part].question}
              </label>
              <span className="text-xs text-slate-500 bg-slate-800 px-2 py-1 rounded">
                {cq.parts[part].marks} Marks • {cq.parts[part].label}
              </span>
            </div>
            <textarea
              className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-slate-200 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all min-h-[100px]"
              placeholder={`Write your answer here...`}
              value={cqAnswers[part]}
              onChange={(e) => updatePart(part, e.target.value)}
              disabled={showFeedback}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default QuestionRenderer;

