import React, { useState, useCallback } from 'react';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import PracticeView from './views/PracticeView';
import ActiveExam from './views/ActiveExam';
import ResultsView from './views/ResultsView';
import { geminiService } from './services/geminiService';
import { Subject, QuestionType, ExamSession, GradingResult } from './types';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(false);
  const [activeSession, setActiveSession] = useState<ExamSession | null>(null);
  const [gradingResults, setGradingResults] = useState<GradingResult[] | null>(null);
  const [sessionAnswers, setSessionAnswers] = useState<Record<string, any>>({});

  const startPractice = async (subject: Subject, chapter: string, type: QuestionType) => {
    setIsLoading(true);
    try {
      let questions = [];
      if (type === 'MCQ') {
        questions = await geminiService.generateMCQs(subject, chapter, 5);
      } else {
        const cq = await geminiService.generateCQ(subject, chapter);
        if (cq) questions = [cq];
      }

      if (questions.length > 0) {
        const newSession: ExamSession = {
          id: Math.random().toString(36).substr(2, 9),
          subject,
          mode: 'Practice',
          startTime: Date.now(),
          questions,
          durationMinutes: type === 'MCQ' ? 10 : 30,
          isCompleted: false
        };
        setActiveSession(newSession);
        setActiveView('active-exam');
      }
    } catch (error) {
      console.error("Failed to start practice", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleFinishExam = async (answers: Record<string, any>) => {
    if (!activeSession) return;
    setSessionAnswers(answers);
    setIsLoading(true);

    try {
      const results: GradingResult[] = [];

      for (const q of activeSession.questions) {
        if (q.type === 'MCQ') {
          const isCorrect = answers[q.id] === q.correctOptionId;
          results.push({
            questionId: q.id,
            obtainedMarks: isCorrect ? 1 : 0,
            maxMarks: 1,
            feedback: isCorrect ? 'Perfect. The concept is clear.' : `Incorrect. Correct answer was ${q.options.find(o => o.id === q.correctOptionId)?.text}. ${q.explanation}`,
            status: isCorrect ? 'Correct' : 'Incorrect'
          });
        } else {
          const cqResult = await geminiService.gradeCQAnswer(q, answers[q.id] || {});
          results.push(...cqResult);
        }
      }

      setGradingResults(results);
      setActiveView('results');
    } catch (error) {
      console.error("Grading failed", error);
    } finally {
      setIsLoading(false);
    }
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard onStartPractice={() => setActiveView('practice')} />;
      case 'practice':
        return <PracticeView onStart={startPractice} isLoading={isLoading} />;
      case 'active-exam':
        return activeSession ? (
          <ActiveExam 
            session={activeSession} 
            onFinish={handleFinishExam} 
            isGrading={isLoading}
          />
        ) : null;
      case 'results':
        return activeSession && gradingResults ? (
          <ResultsView 
            questions={activeSession.questions} 
            answers={sessionAnswers}
            results={gradingResults}
            onBack={() => {
              setActiveSession(null);
              setGradingResults(null);
              setSessionAnswers({});
              setActiveView('dashboard');
            }}
          />
        ) : null;
      case 'analytics':
        return (
          <div className="flex flex-col items-center justify-center h-full text-slate-500">
            <h3 className="text-2xl font-bold mb-4">Detailed Analytics Coming Soon</h3>
            <p>Your performance data is being calculated based on your practices.</p>
          </div>
        );
      default:
        return <Dashboard onStartPractice={() => setActiveView('practice')} />;
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      {renderView()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult } from "../types";

// Initialize the Gemini API client using the required environment variable.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number = 5): Promise<MCQQuestion[]> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate ${count} high-quality board-style MCQ questions for SSC Bangladesh exam. 
      Subject: ${subject}, Chapter: ${chapter}. 
      Follow the 2026 syllabus guidelines.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                  },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      const text = response.text.trim();
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string): Promise<CQQuestion | null> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate one original SSC Creative Question (CQ) with a stem and 4 parts (a, b, c, d).
      Subject: ${subject}, Chapter: ${chapter}.
      A: Knowledge (1 mark), B: Understanding (2 marks), C: Application (3 marks), D: Higher Order (4 marks).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { 
                  type: Type.OBJECT, 
                  properties: { 
                    question: { type: Type.STRING }, 
                    marks: { type: Type.NUMBER }, 
                    label: { type: Type.STRING } 
                  },
                  required: ["question", "marks", "label"]
                },
                b: { 
                  type: Type.OBJECT, 
                  properties: { 
                    question: { type: Type.STRING }, 
                    marks: { type: Type.NUMBER }, 
                    label: { type: Type.STRING } 
                  },
                  required: ["question", "marks", "label"]
                },
                c: { 
                  type: Type.OBJECT, 
                  properties: { 
                    question: { type: Type.STRING }, 
                    marks: { type: Type.NUMBER }, 
                    label: { type: Type.STRING } 
                  },
                  required: ["question", "marks", "label"]
                },
                d: { 
                  type: Type.OBJECT, 
                  properties: { 
                    question: { type: Type.STRING }, 
                    marks: { type: Type.NUMBER }, 
                    label: { type: Type.STRING } 
                  },
                  required: ["question", "marks", "label"]
                }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      const text = response.text.trim();
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, string>): Promise<GradingResult[]> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Grade the following student's answers for an SSC CQ based on Bangladesh Board marking rules.
      Question Stem: ${question.stem}
      A: ${question.parts.a.question}
      B: ${question.parts.b.question}
      C: ${question.parts.c.question}
      D: ${question.parts.d.question}

      Student Answers:
      A: ${answers.a}
      B: ${answers.b}
      C: ${answers.c}
      D: ${answers.d}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      const text = response.text.trim();
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse grading results", e);
      return [];
    }
  }
};

