                className={`py-3 rounded-2xl font-bold transition-all border ${
                  qCount === num 
                  ? 'bg-indigo-600 border-indigo-500 text-white' 
                  : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700 hover:text-slate-300'
                }`}
              >
                {num}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Chapters List */}
      <div className="space-y-4">
        <h3 className="text-sm font-bold text-slate-500 px-2 mb-4 uppercase tracking-[0.2em]">Syllabus 2026 Chapters</h3>
        {filteredSyllabus.length > 0 ? filteredSyllabus.map((chapter) => (
          <button
            key={chapter.id}
            onClick={() => onStart(selectedSubject, chapter.chapterTitle, selectedType, qCount)}
            disabled={isLoading}
            className="w-full bg-slate-900/30 hover:bg-slate-900 border border-slate-800 hover:border-indigo-500/50 p-6 rounded-3xl flex items-center justify-between group transition-all"
          >
            <div className="flex items-center gap-5">
              <div className="w-12 h-12 rounded-2xl bg-slate-800 flex items-center justify-center text-indigo-400 group-hover:bg-indigo-600 group-hover:text-white transition-all font-bold">
                {chapter.chapterNumber}
              </div>
              <div className="text-left">
                <h4 className="font-bold text-slate-200">{chapter.chapterTitle}</h4>
                <p className="text-xs text-slate-500 mt-1 uppercase tracking-wider">{selectedSubject} • {selectedType}</p>
              </div>
            </div>
            {isLoading ? (
              <Loader2 className="animate-spin text-indigo-500" />
            ) : (
              <div className="flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-all">
                <span className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Start Now</span>
                <ChevronRight className="text-indigo-500 group-hover:translate-x-1 transition-all" />
              </div>
            )}
          </button>
        )) : (
          <div className="text-center py-16 bg-slate-900/10 border border-dashed border-slate-800 rounded-[2.5rem]">
            <Library size={48} className="mx-auto text-slate-800 mb-4" />
            <p className="text-slate-500 font-medium">Coming Soon for {selectedSubject}.</p>
            <p className="text-xs text-slate-600 mt-1 uppercase tracking-widest">We are populating 2026 chapters...</p>
          </div>
        )}
      </div>
    </div>
  );
};

