import React from 'react';
import { Question, MCQQuestion, CQQuestion } from '../types';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: any;
  onAnswerChange: (answer: any) => void;
  showFeedback?: boolean;
}

const QuestionRenderer: React.FC<QuestionRendererProps> = ({ 
  question, 
  index, 
  answer, 
  onAnswerChange,
  showFeedback = false 
}) => {
  if (question.type === 'MCQ') {
    const mcq = question as MCQQuestion;
    return (
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
        <div className="flex items-start gap-4 mb-6">
          <span className="flex-shrink-0 w-8 h-8 rounded-lg bg-indigo-600/20 text-indigo-400 flex items-center justify-center font-bold text-sm">
            {index + 1}
          </span>
          <h3 className="text-lg font-medium text-slate-200 leading-relaxed">
            {mcq.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {mcq.options.map((option) => {
            const isSelected = answer === option.id;
            const isCorrect = option.id === mcq.correctOptionId;
            let borderStyle = 'border-slate-800 hover:border-slate-700 hover:bg-slate-800/50';

            if (isSelected) borderStyle = 'border-indigo-500 bg-indigo-500/10 text-indigo-200';
            if (showFeedback) {
              if (isCorrect) borderStyle = 'border-emerald-500 bg-emerald-500/10 text-emerald-200';
              else if (isSelected) borderStyle = 'border-red-500 bg-red-500/10 text-red-200';
            }

            return (
              <button
                key={option.id}
                onClick={() => !showFeedback && onAnswerChange(option.id)}
                disabled={showFeedback}
                className={`flex items-center gap-3 p-4 rounded-xl border transition-all text-left ${borderStyle}`}
              >
                <div className={`w-6 h-6 rounded-full border flex items-center justify-center flex-shrink-0 ${
                  isSelected ? 'border-indigo-500 bg-indigo-500' : 'border-slate-700'
                }`}>
                  {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-white"></div>}
                </div>
                <span className="text-sm md:text-base font-medium">{option.text}</span>
              </button>
            );
          })}
        </div>

        {showFeedback && (
          <div className="mt-6 p-4 bg-slate-800/50 rounded-xl border border-slate-700">
            <h4 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">ব্যাখ্যা (Explanation)</h4>
            <p className="text-sm text-slate-300 leading-relaxed">{mcq.explanation}</p>
          </div>
        )}
      </div>
    );
  }

  const cq = question as CQQuestion;
  const cqAnswers = answer || { a: '', b: '', c: '', d: '' };

  const updatePart = (part: 'a' | 'b' | 'c' | 'd', val: string) => {
    onAnswerChange({ ...cqAnswers, [part]: val });
  };

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
      <div className="bg-slate-950 p-6 rounded-xl border border-slate-800 mb-8">
        <h4 className="text-xs font-bold text-indigo-400 uppercase mb-3 tracking-widest">উদ্দীপক (Stem)</h4>
        <p className="text-slate-200 leading-relaxed whitespace-pre-wrap">{cq.stem}</p>
      </div>

      <div className="space-y-8">
        {(['a', 'b', 'c', 'd'] as const).map((part) => (
          <div key={part} className="space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-slate-300 font-medium flex items-center gap-2">
                <span className="uppercase text-indigo-500 font-bold">{part})</span>
                {cq.parts[part].question}
              </label>
              <span className="text-xs text-slate-500 bg-slate-800 px-2 py-1 rounded">
                {cq.parts[part].marks} নম্বর • {cq.parts[part].label}
              </span>
            </div>
            <textarea
              className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-slate-200 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all min-h-[100px]"
              placeholder={`আপনার উত্তর এখানে লিখুন...`}
              value={cqAnswers[part]}
              onChange={(e) => updatePart(part, e.target.value)}
              disabled={showFeedback}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default QuestionRenderer;

import React, { useState } from 'react';
import { ExamSession, Question, GradingResult } from '../types';
import QuestionRenderer from '../components/QuestionRenderer';
import ExamTimer from '../components/ExamTimer';
import { Send, AlertCircle, CheckCircle2, ChevronRight, ChevronLeft } from 'lucide-react';

interface ActiveExamProps {
  session: ExamSession;
  onFinish: (answers: Record<string, any>) => void;
  isGrading?: boolean;
}

const ActiveExam: React.FC<ActiveExamProps> = ({ session, onFinish, isGrading }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const [isFinishing, setIsFinishing] = useState(false);

  const handleAnswer = (val: any) => {
    setAnswers(prev => ({ ...prev, [session.questions[currentIdx].id]: val }));
  };

  const isLast = currentIdx === session.questions.length - 1;

  const handleFinishRequest = () => {
    setIsFinishing(true);
    onFinish(answers);
  };

  return (
    <div className="max-w-4xl mx-auto pb-24">
      {/* Fixed Sticky Header */}
      <div className="sticky top-0 z-20 bg-slate-950/80 backdrop-blur-md border-b border-slate-800 py-4 px-2 mb-8 flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-white flex items-center gap-3">
            {session.subject} প্র্যাকটিস
            <span className="text-sm font-normal text-slate-500 px-3 py-1 bg-slate-900 rounded-full">
              প্রশ্ন {currentIdx + 1} / {session.questions.length}
            </span>
          </h2>
        </div>
        <div className="flex items-center gap-4">
          {session.mode === 'Exam' && (
            <ExamTimer 
              durationMinutes={session.durationMinutes} 
              onTimeUp={() => onFinish(answers)} 
            />
          )}
          <button
            onClick={handleFinishRequest}
            disabled={isGrading || isFinishing}
            className="flex items-center gap-2 px-6 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-full font-bold transition-all disabled:opacity-50"
          >
            {isGrading ? 'মূল্যায়ন চলছে...' : 'পরীক্ষা জমা দিন'}
            <Send size={18} />
          </button>
        </div>
      </div>

      <div className="space-y-8">
        <QuestionRenderer
          question={session.questions[currentIdx]}
          index={currentIdx}
          answer={answers[session.questions[currentIdx].id]}
          onAnswerChange={handleAnswer}
        />

        {/* Navigation Controls */}
        <div className="flex justify-between items-center mt-12 bg-slate-900/50 p-4 rounded-3xl border border-slate-800">
          <button
            onClick={() => setCurrentIdx(prev => Math.max(0, prev - 1))}
            disabled={currentIdx === 0}
            className="flex items-center gap-2 px-6 py-3 text-slate-400 hover:text-white disabled:opacity-30 transition-all"
          >
            <ChevronLeft /> পূর্ববর্তী
          </button>

          <div className="hidden md:flex gap-1">
            {session.questions.map((_, i) => (
              <button
                key={i}
                onClick={() => setCurrentIdx(i)}
                className={`w-10 h-10 rounded-xl font-bold transition-all ${
                  currentIdx === i 
                  ? 'bg-indigo-600 text-white' 
                  : answers[session.questions[i].id] 
                    ? 'bg-slate-800 text-slate-300' 
                    : 'text-slate-600 hover:bg-slate-800'
                }`}
              >
                {i + 1}
              </button>
            ))}
          </div>

          <button
            onClick={() => !isLast ? setCurrentIdx(prev => prev + 1) : handleFinishRequest()}
            className={`flex items-center gap-2 px-8 py-3 rounded-2xl font-bold transition-all ${
              isLast 
              ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/20' 
              : 'bg-slate-800 text-slate-200 hover:bg-slate-700'
            }`}
          >
            {isLast ? 'সম্পন্ন' : 'পরবর্তী প্রশ্ন'} <ChevronRight size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ActiveExam;

import React, { useRef } from 'react';
import { Question, MCQQuestion, CQQuestion } from '../types';
import { Camera, Image as ImageIcon, X, Paperclip } from 'lucide-react';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: any;
  onAnswerChange: (answer: any) => void;
  showFeedback?: boolean;
}

const QuestionRenderer: React.FC<QuestionRendererProps> = ({ 
  question, 
  index, 
  answer, 
  onAnswerChange,
  showFeedback = false 
}) => {
  const fileInputRefs = {
    a: useRef<HTMLInputElement>(null),
    b: useRef<HTMLInputElement>(null),
    c: useRef<HTMLInputElement>(null),
    d: useRef<HTMLInputElement>(null)
  };

  if (question.type === 'MCQ') {
    const mcq = question as MCQQuestion;
    return (
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
        <div className="flex items-start gap-4 mb-6">
          <span className="flex-shrink-0 w-8 h-8 rounded-lg bg-indigo-600/20 text-indigo-400 flex items-center justify-center font-bold text-sm">
            {index + 1}
          </span>
          <h3 className="text-lg font-medium text-slate-200 leading-relaxed">
            {mcq.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {mcq.options.map((option) => {
            const isSelected = answer === option.id;
            const isCorrect = option.id === mcq.correctOptionId;
            let borderStyle = 'border-slate-800 hover:border-slate-700 hover:bg-slate-800/50';

            if (isSelected) borderStyle = 'border-indigo-500 bg-indigo-500/10 text-indigo-200';
            if (showFeedback) {
              if (isCorrect) borderStyle = 'border-emerald-500 bg-emerald-500/10 text-emerald-200';
              else if (isSelected) borderStyle = 'border-red-500 bg-red-500/10 text-red-200';
            }

            return (
              <button
                key={option.id}
                onClick={() => !showFeedback && onAnswerChange(option.id)}
                disabled={showFeedback}
                className={`flex items-center gap-3 p-4 rounded-xl border transition-all text-left ${borderStyle}`}
              >
                <div className={`w-6 h-6 rounded-full border flex items-center justify-center flex-shrink-0 ${
                  isSelected ? 'border-indigo-500 bg-indigo-500' : 'border-slate-700'
                }`}>
                  {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-white"></div>}
                </div>
                <span className="text-sm md:text-base font-medium">{option.text}</span>
              </button>
            );
          })}
        </div>

        {showFeedback && (
          <div className="mt-6 p-4 bg-slate-800/50 rounded-xl border border-slate-700">
            <h4 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">ব্যাখ্যা (Explanation)</h4>
            <p className="text-sm text-slate-300 leading-relaxed">{mcq.explanation}</p>
          </div>
        )}
      </div>
    );
  }

  const cq = question as CQQuestion;
  const cqAnswers = answer || { 
    a: { text: '', image: null }, 
    b: { text: '', image: null }, 
    c: { text: '', image: null }, 
    d: { text: '', image: null } 
  };

  const updatePartText = (part: 'a' | 'b' | 'c' | 'd', val: string) => {
    onAnswerChange({ ...cqAnswers, [part]: { ...cqAnswers[part], text: val } });
  };

  const handleImageUpload = (part: 'a' | 'b' | 'c' | 'd', file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      onAnswerChange({ 
        ...cqAnswers, 
        [part]: { ...cqAnswers[part], image: reader.result as string } 
      });
    };
    reader.readAsDataURL(file);
  };

  const removeImage = (part: 'a' | 'b' | 'c' | 'd') => {
    onAnswerChange({ 
      ...cqAnswers, 
      [part]: { ...cqAnswers[part], image: null } 
    });
  };

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
      <div className="bg-slate-950 p-6 rounded-xl border border-slate-800 mb-8">
        <div className="flex justify-between items-center mb-3">
          <h4 className="text-xs font-bold text-indigo-400 uppercase tracking-widest">উদ্দীপক (Stem)</h4>
          <span className="px-3 py-1 bg-indigo-600/10 text-indigo-400 rounded-full text-[10px] font-bold uppercase border border-indigo-500/20">সৃজনশীল প্রশ্ন</span>
        </div>
        <p className="text-slate-200 leading-relaxed whitespace-pre-wrap">{cq.stem}</p>
      </div>

      <div className="space-y-10">
        {(['a', 'b', 'c', 'd'] as const).map((part) => (
          <div key={part} className="space-y-4">
            <div className="flex justify-between items-start">
              <label className="text-slate-200 font-bold flex items-center gap-3">
                <span className="w-8 h-8 rounded-lg bg-slate-800 text-indigo-400 flex items-center justify-center font-black uppercase text-sm border border-slate-700">
                  {part}
                </span>
                <span className="leading-tight">{cq.parts[part].question}</span>
              </label>
              <div className="text-right">
                <span className="text-[10px] font-bold text-slate-500 bg-slate-800 px-3 py-1 rounded-lg border border-slate-700">
                  {cq.parts[part].marks} নম্বর • {cq.parts[part].label}
                </span>
              </div>
            </div>

            <div className="space-y-3 pl-11">
              <textarea
                className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 text-slate-200 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all min-h-[120px] text-sm md:text-base"
                placeholder={`আপনার উত্তর এখানে লিখুন অথবা নিচে ছবি আপলোড করুন...`}
                value={cqAnswers[part].text}
                onChange={(e) => updatePartText(part, e.target.value)}
                disabled={showFeedback}
              />

              <div className="flex flex-wrap items-center gap-3">
                <input 
                  type="file" 
                  accept="image/*" 
                  className="hidden" 
                  ref={fileInputRefs[part]}
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleImageUpload(part, file);
                  }}
                />
                <button
                  onClick={() => fileInputRefs[part].current?.click()}
                  disabled={showFeedback}
                  className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-xs font-bold transition-all border border-slate-700"
                >
                  <Camera size={14} />
                  হাতে লেখা উত্তরের ছবি দিন
                </button>

                {cqAnswers[part].image && (
                  <div className="relative group">
                    <img 
                      src={cqAnswers[part].image} 
                      alt="Uploaded" 
                      className="w-16 h-16 object-cover rounded-xl border-2 border-indigo-500 cursor-pointer hover:opacity-80 transition-opacity"
                      onClick={() => window.open(cqAnswers[part].image)}
                    />
                    {!showFeedback && (
                      <button 
                        onClick={() => removeImage(part)}
                        className="absolute -top-2 -right-2 bg-red-600 text-white p-1 rounded-full shadow-lg"
                      >
                        <X size={10} />
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

