import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult, Language } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number, language: Language): Promise<MCQQuestion[]> {
    let specificPrompt = "";
    if (subject === Subject.ENGLISH_1ST) {
      specificPrompt = `If Seen Comprehension, use English For Today Units (1, 2, 3, 6, 10, 11, 13, 16). 
      If Unseen, use topics like Charles Babbage, Einstein, SAARC, etc. 
      Pattern: MCQ (Part A Reading Test).`;
    } else if (subject === Subject.ENGLISH_2ND) {
      specificPrompt = `Topic: English 2nd Paper Grammar. 
      Include items like Suffix/Prefix, Right form of verbs, Tag questions, Connectors, and Changing sentences (Simple/Complex/Compound). 
      Format: Each MCQ should test a specific grammar rule defined in the SSC 2026 syllabus.`;
    }

    const langPrompt = language === 'bn' ? "The questions and explanations must be in Bengali language (বাংলা ভাষা)." : "The questions and explanations must be in English language.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate ${count} board-style MCQ questions for Bangladesh SSC exam. 
      Subject: ${subject}
      Chapter/Unit: ${chapter}
      ${specificPrompt}
      Strictly follow 2026 syllabus pattern.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                  },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    let specificPrompt = "";
    if (subject === Subject.ENGLISH_1ST) {
      specificPrompt = `
      Follow English First Paper Writing Test pattern. 
      If 'Writing' is selected: 
      - Story Clues: Liton's result, Two friends in forest, Two rats bread, King Solomon, Honest woodcutter.
      - Dialogue Topics: Dengue fever, TV merits/demerits, Dhaka visit, Aim in life, Facebook.
      - Pattern: Stem is the clue, parts (a, b, c, d) are student responses/evaluations.`;
    } else if (subject === Subject.ENGLISH_2ND) {
      specificPrompt = `
      Follow English Second Paper Writing Test pattern.
      Generate a task based on:
      - Paragraphs: Load shedding, Street accident, Rural life, etc.
      - Applications: Testimonial, Canteen, Study tour, etc.
      - Compositions: Aim in life, Computer, Tree plantation, etc.
      Stem should describe the writing scenario. Part A/B/C/D should be requirements or structure checks.`;
    }

    const langPrompt = language === 'bn' ? "The stem, questions, and parts must be in Bengali language (বাংলা ভাষা)." : "The stem, questions, and parts must be in English language.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate one original SSC Creative Question (CQ) / Writing Task with a stem and 4 parts (a, b, c, d). 
      Subject: ${subject}
      Chapter/Topic: ${chapter}
      ${specificPrompt}
      Follow 2026 NCTB board pattern exactly.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                b: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                c: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                d: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      return JSON.parse(response.text || 'null');
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    const mcqs = await this.generateMCQs(subject, "Full Syllabus", 15, language);
    const cqs: CQQuestion[] = [];

    const cqPromises = [
      this.generateCQ(subject, "Seen/Unseen or Grammar Applications", language),
      this.generateCQ(subject, "Formal Writing Task", language)
    ];

    const resolvedCqs = await Promise.all(cqPromises);
    resolvedCqs.forEach(cq => { if(cq) cqs.push(cq); });

    return { mcqs, cqs };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const langPrompt = language === 'bn' ? "Provide feedback in Bengali (বাংলা ভাষা)." : "Provide feedback in English.";

    const parts: any[] = [
      { text: `Grade the student's answers for an SSC exam task. 
      Evaluate based on Board marking scheme. 
      Criteria: Clarity, Grammar accuracy (esp. for English 2nd), Structure, and relevance to the topic.
      Topic/Stem: ${question.stem}
      Questions:
      A: ${question.parts.a.question}
      B: ${question.parts.b.question}
      C: ${question.parts.c.question}
      D: ${question.parts.d.question}
      ${langPrompt}` }
    ];

    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const ans = answers[p] || { text: '' };
      parts.push({ text: `Student's Answer for Part ${p.toUpperCase()}: ${ans.text || '[See attached image if available]'}` });
      if (ans.image) {
        const base64Data = ans.image.split(',')[1];
        parts.push({
          inlineData: {
            data: base64Data,
            mimeType: 'image/jpeg'
          }
        });
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse grading", e);
      return [];
    }
  }
};

