import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult, Language } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number, language: Language): Promise<MCQQuestion[]> {
    let specificPrompt = "";
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;

    if (subject === Subject.ENGLISH_1ST) {
      specificPrompt = `If Seen Comprehension, use English For Today Units. All content MUST be in English.`;
    } else if (subject === Subject.MATH) {
      specificPrompt = `Focus on numeric logic and formulas.`;
    } else if (subject === Subject.AGRICULTURE) {
      specificPrompt = `Topic: SSC Agricultural Education (কৃষি শিক্ষা). 
      Chapters: 1 (Technology), 2 (Materials), 4 (Production), 5 (Forestry).
      Focus on soil types, seed quality, livestock breeds, fish farming methods, and nursery management. Use Bengali script.`;
    }

    const langPrompt = effectiveLanguage === 'bn' 
      ? "The questions and explanations must be in Bengali language (বাংলা ভাষা)." 
      : "The questions and explanations must be in English language.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate ${count} board-style MCQ questions for Bangladesh SSC exam. 
      Subject: ${subject}
      Chapter/Unit: ${chapter}
      ${specificPrompt}
      Strictly follow 2026 syllabus pattern.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                  },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    let specificPrompt = "";
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;

    if (subject === Subject.AGRICULTURE) {
      specificPrompt = `Topic: SSC Agricultural Education Creative Question. 
      Structure: A stem (উদ্দীপক) describing a practical agricultural scenario (e.g., a farmer's crop failing, fish in a pond dying, or planning a nursery).
      Follow Board Marking Scheme (1+2+3+4 marks):
      - (ক) জ্ঞানমূলক: সরাসরি তথ্য (e.g., Define Nursery)
      - (খ) অনুধাবনমূলক: ধারণা ব্যাখ্যা (e.g., Explain why soil testing is needed)
      - (গ) প্রয়োগমূলক: উদ্দীপকের সমস্যার সমাধান বা পদ্ধতি বর্ণনা।
      - (ঘ) উচ্চতর দক্ষতা: ঘটনার গুরুত্ব বা দীর্ঘমেয়াদী প্রভাব বিশ্লেষণ।
      Use clear Bengali language.`;
    }

    const langPrompt = effectiveLanguage === 'bn' 
      ? "The stem, questions, and parts must be in Bengali language (বাংলা ভাষা)." 
      : "The stem, questions, and parts must be in English language.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate one original SSC Creative Question (CQ) / Writing Task with a stem and 4 parts (a, b, c, d). 
      Subject: ${subject}
      Chapter/Topic: ${chapter}
      ${specificPrompt}
      Follow 2026 NCTB board pattern exactly.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                b: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                c: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                d: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      return JSON.parse(response.text || 'null');
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    const mcqs = await this.generateMCQs(subject, "Full Syllabus", 15, language);
    const cqs: CQQuestion[] = [];

    const cqPromises = [
      this.generateCQ(subject, "Agricultural Technology/Materials", language),
      this.generateCQ(subject, "Production/Forestry", language)
    ];

    const resolvedCqs = await Promise.all(cqPromises);
    resolvedCqs.forEach(cq => { if(cq) cqs.push(cq); });

    return { mcqs, cqs };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.includes('Paper') || question.stem.toLowerCase().includes('english');
    const effectiveLanguage = isEnglishSubject ? 'en' : language;

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Provide feedback in Bengali (বাংলা ভাষা)." 
      : "Provide feedback in English.";

    const parts: any[] = [
      { text: `Grade the student's answers for an SSC exam task. 
      Evaluate based on Board marking scheme. 
      For AGRICULTURE: Check knowledge of farming techniques, livestock care, and species names.
      Criteria: Accuracy, Relevance, and Completeness.
      Topic/Stem: ${question.stem}
      Questions:
      A: ${question.parts.a.question}
      B: ${question.parts.b.question}
      C: ${question.parts.c.question}
      D: ${question.parts.d.question}
      ${langPrompt}` }
    ];

    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const ans = answers[p] || { text: '' };
      parts.push({ text: `Student's Answer for Part ${p.toUpperCase()}: ${ans.text || '[See attached image if available]'}` });
      if (ans.image) {
        const base64Data = ans.image.split(',')[1];
        parts.push({
          inlineData: {
            data: base64Data,
            mimeType: 'image/jpeg'
          }
        });
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse grading", e);
      return [];
    }
  }
};

