export type Language = 'bn' | 'en';

export interface SyllabusItem {
  id: string;
  subject: Subject;
  chapterNumber: number;
  chapterTitle: string;
  topics: string[];
}

export type QuestionType = 'MCQ' | 'CQ' | 'FULL';

export interface MCQOption {
  id: string;
  text: string;
}

export interface MCQQuestion {
  id: string;
  type: 'MCQ';
  chapter: string;
  question: string;
  options: MCQOption[];
  correctOptionId: string;
  explanation: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
}

export interface CQQuestion {
  id: string;
  type: 'CQ';
  chapter: string;
  stem: string;
  parts: {
    a: { question: string; marks: number; label: string };
    b: { question: string; marks: number; label: string };
    c: { question: string; marks: number; label: string };
    d: { question: string; marks: number; label: string };
  };
}

export type Question = MCQQuestion | CQQuestion;

export interface ExamSession {
  id: string;
  subject: Subject;
  mode: 'Practice' | 'Exam' | 'BOARD';
  startTime: number;
  questions: Question[];
  durationMinutes: number;
  isCompleted: boolean;
  language: Language;
}

export interface GradingResult {
  questionId: string;
  obtainedMarks: number;
  maxMarks: number;
  feedback: string;
  status: 'Correct' | 'Partial' | 'Incorrect';
}

export interface SessionHistory {
  sessionId: string;
  subject: Subject;
  timestamp: number;
  score: number;
  totalMarks: number;
  accuracy: number;
  durationMinutes: number;
  mode: 'Practice' | 'Exam' | 'BOARD';
}

import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult, Language } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number, language: Language): Promise<MCQQuestion[]> {
    let specificPrompt = "";
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;

    if (subject === Subject.BANGLA_1ST) {
      specificPrompt = `Focus on the Bangladesh SSC 2026 Short Syllabus.
      Chapters to consider: প্রত্যুপকার, সুভা, বই পড়া, আম আঁটির ভেঁপু, মানুষ, মুহাম্মদ (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম), শিক্ষা ও মনুষ্যত্ব, নিমগাছ, কপোতাক্ষ নদ, জীবন বিনিময়, ওমর ফারুক, সেই দিন এই মাঠ, বৃষ্টি, বৈশাখ, উপন্যাস্য ১৯৭১. 
      Ensure questions cover author information, word meanings, and core themes.`;
    } else if (subject === Subject.MATH) {
      specificPrompt = `Focus on numeric logic and formulas.`;
    } else if (subject === Subject.AGRICULTURE) {
      specificPrompt = `Focus on soil types, livestock, and nursery management.`;
    } else if (subject === Subject.HISTORY || subject === Subject.GEOGRAPHY || subject === Subject.CIVICS) {
      specificPrompt = `Focus on SSC Humanities curriculum 2026. Focus on historical dates, geographic features, and civic duties.`;
    }

    const langPrompt = effectiveLanguage === 'bn' 
      ? "The questions and explanations must be in Bengali language (বাংলা ভাষা)." 
      : "The questions and explanations must be in English language.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate ${count} board-style MCQ questions for Bangladesh SSC exam. 
      Subject: ${subject}
      Chapter/Unit: ${chapter}
      ${specificPrompt}
      Strictly follow 2026 syllabus pattern for Humanities.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                  },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    let specificPrompt = "";
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;

    if (subject === Subject.BANGLA_1ST) {
      specificPrompt = `Topic: SSC Bangla 1st Paper. Use the specific context of chapters like 'প্রত্যুপকার' or 'সুভা' or 'শিক্ষা ও মনুষ্যত্ব'.
      Structure: A stem (উদ্দীপক) reflecting themes of human values, society, or nature as per the 15 chapters list.
      Parts (1+2+3+4 marks): 
      - (ক) জ্ঞানমূলক: সরাসরি তথ্য।
      - (খ) অনুধাবনমূলক: ধারণা ব্যাখ্যা।
      - (গ) প্রয়োগমূলক: উদ্দীপকের সাথে পাঠ্যবইয়ের মিল/অমিল।
      - (ঘ) উচ্চতর দক্ষতা: বিচার-বিশ্লেষণ বা মূল্যায়ণ।`;
    } else if (subject === Subject.HISTORY || subject === Subject.GEOGRAPHY || subject === Subject.CIVICS) {
      specificPrompt = `Focus on SSC Humanities Board Pattern 2026. The stem should describe a real-world scenario relating to heritage, administration, or environmental issues.`;
    }

    const langPrompt = effectiveLanguage === 'bn' 
      ? "The stem, questions, and parts must be in Bengali language (বাংলা ভাষা)." 
      : "The stem, questions, and parts must be in English language.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate one original SSC Creative Question (CQ) with a stem and 4 parts (a, b, c, d). 
      Subject: ${subject}
      Chapter/Topic: ${chapter}
      ${specificPrompt}
      Follow 2026 NCTB board pattern exactly.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                b: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                c: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                d: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      return JSON.parse(response.text || 'null');
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    const mcqs = await this.generateMCQs(subject, "Full Syllabus 2026", 15, language);
    const cqs: CQQuestion[] = [];

    const cqPromises = [
      this.generateCQ(subject, "Core Themes & Values", language),
      this.generateCQ(subject, "Socio-Political Aspects", language)
    ];

    const resolvedCqs = await Promise.all(cqPromises);
    resolvedCqs.forEach(cq => { if(cq) cqs.push(cq); });

    return { mcqs, cqs };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.includes('Paper') || question.stem.toLowerCase().includes('english');
    const effectiveLanguage = isEnglishSubject ? 'en' : language;

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Provide feedback in Bengali (বাংলা ভাষা)." 
      : "Provide feedback in English.";

    const parts: any[] = [
      { text: `Grade the student's answers for an SSC exam task. 
      Evaluate based on Board marking scheme.
      Topic/Stem: ${question.stem}
      Questions:
      A: ${question.parts.a.question}
      B: ${question.parts.b.question}
      C: ${question.parts.c.question}
      D: ${question.parts.d.question}
      ${langPrompt}` }
    ];

    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const ans = answers[p] || { text: '' };
      parts.push({ text: `Student's Answer for Part ${p.toUpperCase()}: ${ans.text || '[See attached image]'}` });
      if (ans.image) {
        const base64Data = ans.image.split(',')[1];
        parts.push({
          inlineData: {
            data: base64Data,
            mimeType: 'image/jpeg'
          }
        });
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse grading", e);
      return [];
    }
  }
};

