    const cqs: CQQuestion[] = [];
    const cqPromises = [
      this.generateCQ(subject, "Core Board Question Pattern Set 1", language),
      this.generateCQ(subject, "Core Board Question Pattern Set 2", language)
    ];
    const resolvedCqs = await Promise.all(cqPromises);
    resolvedCqs.forEach(cq => { if(cq) cqs.push(cq); });
    return { mcqs, cqs };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.includes('Paper') || question.stem.toLowerCase().includes('english') || (question.chapter && question.chapter.toLowerCase().includes('english'));
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const langPrompt = effectiveLanguage === 'bn' ? "Provide feedback in Bengali." : "Provide feedback in English.";

    const parts: any[] = [{ text: `Grade SSC Board-style answers. For Science, check conceptual clarity, formula application, and units. ${langPrompt}` }];

    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const qPart = question.parts[p];
      if (qPart && qPart.question) {
        const ans = answers[p] || { text: '' };
        parts.push({ text: `Question ${p.toUpperCase()} (${qPart.marks} marks): ${qPart.question}\nStudent Answer: ${ans.text || '[Image Attachment]'}` });
        if (ans.image) {
          parts.push({ inlineData: { data: ans.image.split(',')[1], mimeType: 'image/jpeg' } });
        }
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse grading", e);
      return [];
    }
  }
};

