                            </span>
                          </div>
                          <p className="text-sm text-slate-400 italic">
                            {partAns?.text ? `"${partAns.text}"` : '[উত্তর দেওয়া হয়নি / চিত্র সংযুক্তি]'}
                          </p>
                        </div>
                      );
                    })}
