export default ExamHistoryView;

import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult, Language } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const CORE_BOARD_INSTRUCTIONS = `
STRICT COMPLIANCE: Bangladesh NCTB SSC Board Pattern (Short Syllabus 2026).
QUESTION STYLES:
1. MCQs must include:
   - Simple Recall (Direct facts).
   - Multiple Completion (i, ii, iii statements; Options: A. i & ii, B. ii & iii, etc.).
   - Situation-based (Small stem followed by 2 questions).
2. Creative Questions (CQ):
   - (ক) Knowledge: Direct textbook fact.
   - (খ) Comprehension: Explain 'why' or 'how' a concept works.
   - (গ) Application: Apply textbook concept to the provided Stimulus (উদ্দীপক).
   - (ঘ) Higher Order: Critical analysis/evaluation of the situation.
`;

const SUBJECT_PROMPTS = {
  [Subject.BANGLA_1ST]: `
    - CQ Stem: Must be a short poem snippet or a unique scenario reflecting textbook themes.
    - Part (ক): Author's name, publication year, or direct fact.
    - Part (খ): Deep meaning of a specific line.
  `,
  [Subject.HISTORY]: `
    - CQ Stem: Use modern-day analogies to historical events. 
    - Example: A village leader's behavior mirroring a Mughal Emperor or a British Governor.
    - Topics: Ancient/Medieval Bengal, 1970 Elections, Liberation War.
  `,
  [Subject.MATH]: `
    - MCQ: Include property-based questions and calculation-based.
    - CQ Stem: Real-world scenario (e.g., area of a garden, age of father/son) leading to equations.
  `,
  [Subject.ENGLISH_1ST]: `
    - MCQ: Synonyms, Antonyms, and inference from seen passages.
    - Writing: Formal/Informal letters, Paragraphs, Graphs/Charts.
  `
};

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number, language: Language): Promise<MCQQuestion[]> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Questions and explanations MUST be in Bengali (বাংলা ভাষা). Use standard board terminology." 
      : "Questions and explanations MUST be in English.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      Generate ${count} Board-style MCQs. 
      Important: Ensure at least 30% are 'Multiple Completion' type (i, ii, iii statements).
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING, description: "Include i, ii, iii statements here if it's a multiple completion type." },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                  },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Content MUST be in Bengali (বাংলা ভাষা)." 
      : "Content MUST be in English.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      Generate a HIGH QUALITY Board Standard Creative Question (CQ) with a high-quality stimulus (উদ্দীপক).
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING, description: "The Stimulus (উদ্দীপক) in 4-6 sentences." },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                b: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                c: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                d: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      return JSON.parse(response.text || 'null');
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    // Generate a standardized Board Mock paper
    // Usually 30 MCQ and 11 CQ (student answers 7), but here we generate a representative sample
    const mcqs = await this.generateMCQs(subject, "Syllabus 2026", 30, language);
    const cqs: CQQuestion[] = [];
    const cqPromises = Array(4).fill(null).map((_, i) => 
      this.generateCQ(subject, `Board Pattern Set ${i+1}`, language)
    );
    const resolvedCqs = await Promise.all(cqPromises);
    resolvedCqs.forEach(cq => { if(cq) cqs.push(cq); });
    return { mcqs, cqs };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.toLowerCase().includes('english') || (question.chapter && question.chapter.toLowerCase().includes('english'));
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const langPrompt = effectiveLanguage === 'bn' ? "Feedback in Bengali." : "Feedback in English.";

    const parts: any[] = [{ text: `Strictly grade this answer following the NCTB SSC Board Marking Policy. 
    Consider clarity, terminology, and how well the student related (c) and (d) to the stem. ${langPrompt}` }];

    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const qPart = question.parts[p];
      if (qPart) {
        const ans = answers[p] || { text: '' };
        parts.push({ text: `Part ${p.toUpperCase()} (${qPart.marks} marks): ${qPart.question}\nStudent Answer: ${ans.text || '[Image/Empty]'}` });
        if (ans.image) {
          parts.push({ inlineData: { data: ans.image.split(',')[1], mimeType: 'image/jpeg' } });
        }
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse grading", e);
      return [];
    }
  }
};

import React, { useRef } from 'react';
import { Question, MCQQuestion, CQQuestion } from '../types';
import { Camera, Image as ImageIcon, X, Paperclip, AlertTriangle } from 'lucide-react';

interface QuestionRendererProps {
  question: Question;
  index: number;
  answer: any;
  onAnswerChange: (answer: any) => void;
  showFeedback?: boolean;
}

const QuestionRenderer: React.FC<QuestionRendererProps> = ({ 
  question, 
  index, 
  answer, 
  onAnswerChange,
  showFeedback = false 
}) => {
  const fileInputRefs = {
    a: useRef<HTMLInputElement>(null),
    b: useRef<HTMLInputElement>(null),
    c: useRef<HTMLInputElement>(null),
    d: useRef<HTMLInputElement>(null)
  };

  if (!question) {
    return (
      <div className="bg-red-950/20 border border-red-900 p-6 rounded-3xl text-center">
        <AlertTriangle className="mx-auto text-red-500 mb-2" size={32} />
        <h3 className="text-red-200 font-bold">প্রশ্ন পাওয়া যায়নি</h3>
      </div>
    );
  }

  if (question.type === 'MCQ') {
    const mcq = question as MCQQuestion;
    return (
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
        <div className="flex items-start gap-4 mb-6">
          <span className="flex-shrink-0 w-8 h-8 rounded-lg bg-indigo-600/20 text-indigo-400 flex items-center justify-center font-bold text-sm">
            {index + 1}
          </span>
          <div className="flex-1">
            <h3 className="text-lg font-medium text-slate-200 leading-relaxed whitespace-pre-wrap">
              {mcq.question}
            </h3>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {(mcq.options || []).map((option) => {
            const isSelected = answer === option.id;
            const isCorrect = option.id === mcq.correctOptionId;
            let borderStyle = 'border-slate-800 hover:border-slate-700 hover:bg-slate-800/50';

            if (isSelected) borderStyle = 'border-indigo-500 bg-indigo-500/10 text-indigo-200';
            if (showFeedback) {
              if (isCorrect) borderStyle = 'border-emerald-500 bg-emerald-500/10 text-emerald-200';
              else if (isSelected) borderStyle = 'border-red-500 bg-red-500/10 text-red-200';
            }

            return (
              <button
                key={option.id}
                onClick={() => !showFeedback && onAnswerChange(option.id)}
                disabled={showFeedback}
                className={`flex items-center gap-3 p-4 rounded-xl border transition-all text-left ${borderStyle}`}
              >
                <div className={`w-6 h-6 rounded-full border flex items-center justify-center flex-shrink-0 ${
                  isSelected ? 'border-indigo-500 bg-indigo-500' : 'border-slate-700'
                }`}>
                  {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-white"></div>}
                </div>
                <span className="text-sm md:text-base font-medium">{option.text}</span>
              </button>
            );
          })}
        </div>

        {showFeedback && (
          <div className="mt-6 p-4 bg-slate-800/50 rounded-xl border border-slate-700">
            <h4 className="text-xs font-bold uppercase text-slate-500 mb-2 tracking-wider">ব্যাখ্যা (Board Explanation)</h4>
            <p className="text-sm text-slate-300 leading-relaxed">{mcq.explanation}</p>
          </div>
        )}
      </div>
    );
  }

  const cq = question as CQQuestion;

  if (!cq.parts || typeof cq.parts !== 'object' || !cq.parts.a) {
    return (
      <div className="bg-red-950/20 border border-red-900 p-6 rounded-3xl text-center">
        <AlertTriangle className="mx-auto text-red-500 mb-2" size={32} />
        <h3 className="text-red-200 font-bold">সৃজনশীল প্রশ্ন লোড করতে সমস্যা হয়েছে</h3>
      </div>
    );
  }

  const cqAnswers = answer || { 
    a: { text: '', image: null }, 
    b: { text: '', image: null }, 
    c: { text: '', image: null }, 
    d: { text: '', image: null } 
  };

  const updatePartText = (part: 'a' | 'b' | 'c' | 'd', val: string) => {
    onAnswerChange({ ...cqAnswers, [part]: { ...(cqAnswers[part] || {}), text: val } });
  };

  const handleImageUpload = (part: 'a' | 'b' | 'c' | 'd', file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      onAnswerChange({ 
        ...cqAnswers, 
        [part]: { ...(cqAnswers[part] || {}), image: reader.result as string } 
      });
    };
    reader.readAsDataURL(file);
  };

  const removeImage = (part: 'a' | 'b' | 'c' | 'd') => {
    onAnswerChange({ 
      ...cqAnswers, 
      [part]: { ...(cqAnswers[part] || {}), image: null } 
    });
  };

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 mb-6">
      <div className="bg-slate-950 p-6 rounded-xl border border-slate-800 mb-8">
        <div className="flex justify-between items-center mb-3">
          <h4 className="text-xs font-bold text-indigo-400 uppercase tracking-widest">উদ্দীপক (Stem)</h4>
          <span className="px-3 py-1 bg-amber-600/10 text-amber-500 rounded-full text-[10px] font-bold uppercase border border-amber-500/20">বোর্ড স্ট্যান্ডার্ড সৃজনশীল</span>
        </div>
        <p className="text-slate-200 leading-relaxed whitespace-pre-wrap font-medium bg-slate-900/40 p-4 rounded-xl border border-slate-800/50">{cq.stem}</p>
      </div>

      <div className="space-y-10">
        {(['a', 'b', 'c', 'd'] as const).map((part) => {
          const partData = cq.parts[part];
          if (!partData) return null;

          return (
            <div key={part} className="space-y-4">
              <div className="flex justify-between items-start">
                <label className="text-slate-200 font-bold flex items-center gap-3">
                  <span className="w-8 h-8 rounded-lg bg-slate-800 text-indigo-400 flex items-center justify-center font-black uppercase text-sm border border-slate-700">
                    {part}
                  </span>
                  <span className="leading-tight">{partData.question}</span>
                </label>
                <div className="text-right">
                  <span className="text-[10px] font-bold text-slate-500 bg-slate-800 px-3 py-1 rounded-lg border border-slate-700">
                    {partData.marks} নম্বর • {partData.label}
                  </span>
                </div>
              </div>

              <div className="space-y-3 pl-11">
                <textarea
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 text-slate-200 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all min-h-[120px] text-sm md:text-base"
                  placeholder={`আপনার উত্তর এখানে লিখুন (বোর্ড পরীক্ষায় এই অংশের জন্য ${partData.marks} মার্কস বরাদ্দ থাকে)...`}
                  value={cqAnswers[part]?.text || ''}
                  onChange={(e) => updatePartText(part, e.target.value)}
                  disabled={showFeedback}
                />

                <div className="flex flex-wrap items-center gap-3">
                  <input 
                    type="file" 
                    accept="image/*" 
                    className="hidden" 
                    ref={fileInputRefs[part]}
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) handleImageUpload(part, file);
                    }}
                  />
                  <button
                    onClick={() => fileInputRefs[part].current?.click()}
                    disabled={showFeedback}
                    className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-xs font-bold transition-all border border-slate-700"
                  >
                    <Camera size={14} />
                    ছবি আপলোড (হাতে লেখা উত্তর)
                  </button>

                  {cqAnswers[part]?.image && (
                    <div className="relative group">
                      <img 
                        src={cqAnswers[part].image} 
                        alt="Uploaded" 
                        className="w-16 h-16 object-cover rounded-xl border-2 border-indigo-500 cursor-pointer"
                        onClick={() => window.open(cqAnswers[part].image)}
                      />
                      {!showFeedback && (
                        <button 
                          onClick={() => removeImage(part)}
                          className="absolute -top-2 -right-2 bg-red-600 text-white p-1 rounded-full shadow-lg"
                        >
                          <X size={10} />
                        </button>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default QuestionRenderer;

